        internal sealed class CharacterBinderComparer : IComparer<IReadOnlyCharacterBinder>
        {
            public static readonly CharacterBinderComparer Default = new CharacterBinderComparer();
            public int Compare(IReadOnlyCharacterBinder? a, IReadOnlyCharacterBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                return Comparer<CharacterId>.Default.Compare(a.Id, b.Id);
            }
        }

        internal sealed class CharacterBinderIdTieBreakComparer : IComparer<IReadOnlyCharacterBinder>
        {
            private readonly IComparer<IReadOnlyCharacterBinder> _inner;
            public CharacterBinderIdTieBreakComparer(IComparer<IReadOnlyCharacterBinder> inner) { _inner = inner; }
            public int Compare(IReadOnlyCharacterBinder? a, IReadOnlyCharacterBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                var c = _inner.Compare(a, b);
                if (c != 0) return c;
                return Comparer<CharacterId>.Default.Compare(a.Id, b.Id);
            }
        }
    }
